import yaml
from openapi3 import OpenAPI

def test_regular_security_requirements():
    """Test regular security requirements (existing functionality)."""
    print("Testing regular security requirements...")

    schema = {
        "openapi": "3.0.3",
        "info": {"title": "", "version": "0.0.0"},
        "paths": {
            "/test/": {
                "get": {
                    "operationId": "test_op",
                    "responses": {"200": {"description": "OK"}},
                    "security": [
                        {"apiKey": []},
                        {"oauth2": ["read", "write"]}
                    ]
                }
            }
        },
        "components": {
            "securitySchemes": {
                "apiKey": {"type": "apiKey", "in": "header", "name": "X-API-Key"},
                "oauth2": {"type": "oauth2", "flows": {}}
            }
        }
    }

    try:
        api = OpenAPI(schema)
        op = api.paths['/test/'].get
        assert len(op.security) == 2
        # First security requirement
        assert op.security[0].name == "apiKey"
        assert op.security[0].types == []
        # Second security requirement  
        assert op.security[1].name == "oauth2"
        assert op.security[1].types == ["read", "write"]
        print("✓ Regular security requirements work correctly")
        return True
    except Exception as e:
        print(f"✗ Regular security requirements failed: {e}")
        return False

